$ErrorActionPreference='Stop'
Set-Location -LiteralPath (Split-Path -Parent $PSScriptRoot)
# Captured models only; no compilation, new battle, or old guarded tool execution.
$controls=@(foreach($seed in @(7,19,41)){(Get-Content "TestResults/courts-native-v0240-control-seed$seed.json" -Raw|ConvertFrom-Json).model})
$candidate=(Get-Content TestResults/courts-native-v0240-late-upgrade-seed7.json -Raw|ConvertFrom-Json).model
$base=@($controls|Where-Object Seed -eq 7)[0]
foreach($r in $controls){if($r.CompletedOrders -ne 26 -or $r.Spent -ne 1095 -or $r.Towers -ne 18 -or $r.Kills -ne 780 -or $r.Core -ne 300 -or $r.FinalFired -ne 10 -or $r.MaxDelay -gt .051 -or @($r.FinalTowers|Where-Object { $_.Site -eq 9 -and $_.Shots -eq 0 }).Count -ne 1){throw 'Recorded control differs'}}
if($candidate.Spent -ne 1085 -or $candidate.Credits -ne $base.Credits+10 -or $candidate.Towers -ne 17 -or $candidate.CompletedOrders -ne 26 -or $candidate.Core -ne 300 -or $candidate.Kills -ne 780 -or ($candidate.Cards -join '/') -cne ($base.Cards -join '/')){throw 'Recorded one-order pilot differs'}
for($i=0;$i -lt 25;$i++){if($candidate.PurchaseLog[$i] -cne $base.PurchaseLog[$i] -or [math]::Abs($candidate.ActualTimes[$i]-$base.ActualTimes[$i]) -gt .0001){throw 'Earlier policy differs'}}
if($base.PurchaseLog[25] -notmatch 'build Autocannon @9$' -or $candidate.PurchaseLog[25] -notmatch 'upgrade Autocannon @3$'){throw 'Last choice differs'}
$record=[ordered]@{created=(Get-Date -Format o);task=252;newControlModels=3;newLimitedCandidateModels=1;modelSnapshotsPreserved=$true;secondAddTypeFailedBeforeSeed19ModelAndPartialPreserved=$true;productApkAvdNativeChanged=$false;nativeExactReplay=$false;nativeSeedUnknown=$true;cardPreferences='Ballistic/Range/Ballistic with first-offer fallback';actualControlCards=@($controls|Select-Object Seed,Cards);controls=@($controls|Select-Object Seed,State,Core,Time,Spent,Credits,Towers,FinalFired,RecentPeak,MaxDelay,KindShots,KindDamage,FinalTowers);lastBuild9ZeroShotsInAllThree=$true;pilot=@{seed=7;onlyLast169p4Build9ChangedToUpgrade3=$true;first25ActualReceiptsAndTimesEqual=$true;cardsEqual=$true;oldSpend=1095;newSpend=1085;unreinvestedDifference=10;oldTowers=18;newTowers=17;oldTime=$base.Time;newTime=$candidate.Time;secondsSaved=$base.Time-$candidate.Time;core=300;finalFired=$candidate.FinalFired;recentPeak=$candidate.RecentPeak};decision='No product/stat/lesson change. One-card-policy pilot is too narrow for universal upgrade superiority; current range/LIVE choices remain. Do not force all18 towers to fire or call model enjoyment.';candidateOtherSeedsNotRun=$true;humanFunTested=$false}
$record|ConvertTo-Json -Depth 10|Set-Content TestResults/courts-native-v0240-comparison.json
'PASS: four recorded models; native tenths/price/order scope; final-tower ID shots separated from consumed materials; no new simulation.'
